import { withDottedCircles } from "../../utils/thaiText";
import { PlayAudioButton } from "./PlayAudioButton";

interface Props {
	character: string;
	/** Tailwind size class, e.g. "text-8xl" or "text-[10rem]" */
	className?: string;
	audioUrl?: string;
	hideAudio?: boolean;
	/** CSS color value, e.g. from consonantClassColor.classColor(). Omit for default text color. */
	color?: string;
}

export function ThaiCharDisplay({
	character,
	className,
	audioUrl,
	hideAudio,
	color,
}: Props) {
	return (
		<div className="flex items-center justify-center">
			<span
				className={`thai font-normal ${className ?? "text-8xl"}`}
				style={{ lineHeight: 1.15, color }}
			>
				{withDottedCircles(character)}
			</span>
			{audioUrl && !hideAudio && (
				<PlayAudioButton audioUrl={audioUrl} className="ml-3 w-10 h-10" />
			)}
		</div>
	);
}
