12		interval: number;
13	}
14	
15	interface QuizCardView {
16		id: string;
17		question: string;
18		correctAnswer: string;
19		choices: readonly string[];
20		audioUrl?: string;
21		srs?: SrsData;
22	}
23	
24	interface Props {
25		card: QuizCardView;
26		onRate: (rating: RecallRating) => void;
27	}
28	
29	export function Flashcard({ card, onRate }: Props) {
30		const [revealed, setRevealed] = useState(false);
31	
32		const cardProperty =
33			"property" in card ? (card as Record<string, unknown>).property : null;
34		// Both are "hear it, then recall the meaning" cards — vocab/symbol's own
35		// audioRecognition property and a sentence's listeningComprehension
36		// property (which has no symbolCharacter/promptWord of its own for the
37		// boxes below to key off, so without this it would fall through to no
38		// audio at all) — mirrors MultipleChoice's playsAudioUpfront.
39		const playsAudioUpfront =
40			cardProperty === "audioRecognition" ||
41			cardProperty === "listeningComprehension";
42		const hideAudioHint =
43			cardProperty === "recognition" || cardProperty === "initialSound";
44		const symbolChar =
45			"symbolCharacter" in card
46				? ((card as Record<string, unknown>).symbolCharacter as string)
47				: "";
48		const symbolClass =
49			"consonantClass" in card
50				? ((card as Record<string, unknown>).consonantClass as string | undefined)
51				: undefined;
52		const promptWord =
53			"promptWord" in card
54				? ((card as Record<string, unknown>).promptWord as string)
55				: "";
56		// Every other card shape with audio (symbol, vocab) already gets a player
57		// via the boxes below — this is only true for a shape with none of them,
58		// which today means a sentence's `selfValidation` card: its `audioUrl` is
59		// the *answer's* pronunciation, so it belongs in the reveal, not before
60		// it (hearing it first would answer the challenge — see
61		// `SentenceReadingChallenge`'s own doc comment for the same rule).
62		const hasTopAudio =
63			playsAudioUpfront || Boolean(symbolChar) || Boolean(promptWord);
64	
65		const stage = card.srs
66			? SrsStage.fromScheduleData(card.srs.learningStep, card.srs.interval)
67			: null;
68	
69		// Reset during render, not in an effect: an effect resets after paint, and
70		// iOS Safari then shows a frame of the new card with the answer already
71		// revealed. See `useResetOnCardChange`.
72		useResetOnCardChange(card.id, () => {
73			setRevealed(false);
74		});
75	
76		useEffect(() => {
77			if (playsAudioUpfront && card.audioUrl) {
78				new Audio(card.audioUrl).play().catch(() => {});
79			}
80		}, [playsAudioUpfront, card.audioUrl]);
81	
82		// biome-ignore lint/correctness/useExhaustiveDependencies: fires once per reveal, not on every audioUrl/hasTopAudio identity change
83		useEffect(() => {
84			if (revealed && !hasTopAudio && card.audioUrl) {
85				new Audio(card.audioUrl).play().catch(() => {});
86			}
87		}, [revealed]);
88	
89		const handleReveal = useCallback(() => {
90			setRevealed(true);
91		}, []);
92	
93		const handleRate = useCallback(
94			(rating: RecallRating) => {
95				onRate(rating);
96			},
97			[onRate],
98		);
99	
100		useEffect(() => {
101			if (revealed) return;
102			const handler = (e: KeyboardEvent) => {
103				if (e.key === " ") {
104					e.preventDefault();
105					handleReveal();
106				}
107			};
108			window.addEventListener("keydown", handler);
109			return () => window.removeEventListener("keydown", handler);
110		}, [revealed, handleReveal]);
111	
112		return (
113			<div className="space-y-6">
114				<div
115					className="relative rounded-xl p-4"
116					style={{
117						border: "1px solid var(--color-border)",
118						background: "var(--color-surface)",
119					}}
120				>
121					{stage && (
122						<div className="absolute top-3 right-3">
123							<StageDot stageName={stage.name} />
124						</div>
125					)}
126	
127					{playsAudioUpfront && card.audioUrl ? (
128						<div className="text-center">
129							<button
130								type="button"
131								onClick={() => {
132									if (card.audioUrl) {
133										new Audio(card.audioUrl).play().catch(() => {});
134									}
135								}}
136								className="inline-flex items-center justify-center w-24 h-24 rounded-full transition-colors text-5xl"
137								style={{
138									background: "var(--color-surface-2)",
139									color: "var(--color-primary)",
140								}}
141								aria-label="Replay pronunciation"
142							>
143								🔊
144							</button>
145						</div>
146					) : symbolChar ? (
147						<div className="text-center">
148							<ThaiCharDisplay
149								character={symbolChar}
150								className="text-8xl"
151								audioUrl={card.audioUrl}
152								hideAudio={hideAudioHint}
153								color={classColor(symbolClass)}
154							/>
155						</div>
156					) : promptWord ? (
157						<div className="text-center">
158							<ThaiCharDisplay
159								character={promptWord}
160								className="text-6xl"
161								audioUrl={card.audioUrl}
162							/>
163						</div>
164					) : null}
165	
166					<p
167						className="text-center text-lg"
168						style={{ color: "var(--color-text-muted)" }}
169					>
170						{card.question}
171					</p>
172				</div>
173	
174				{!revealed ? (
175					<button
176						type="button"
177						onClick={handleReveal}
178						className="w-full py-4 rounded-xl text-lg font-semibold transition-colors"
179						style={{
180							background: "var(--color-surface-2)",
181							color: "var(--color-text)",
182						}}
183					>
184						Show Answer <span className="text-xs opacity-50 ml-1">(Space)</span>
185					</button>
186				) : (
187					<div
188						style={{ animation: "slideUp 0.25s ease-out" }}
189						className="space-y-6"
